"""Cloud-Dog AI email/PDF branding — logo header + website footer applied to every
HTML output. The footer also acts as a clear end-of-content separator so trailing
inline (CID) attachment images read as attachments, not stray body content."""

BRAND_NAME = "Cloud-Dog AI"
WEBSITE = "https://www.cloud-dog.ai"
BRAND_LOGO_CID = "clouddogbrandlogo"
CLOUD_DOG_LOGO_B64 = ""


def _header(logo_src: str) -> str:
    return (
        '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" '
        'style="border-collapse:collapse;margin:0 0 10px 0"><tr>'
        '<td style="padding:8px 4px;border-bottom:2px solid #0f2037;vertical-align:middle">'
        f'<img src="{logo_src}" width="34" height="34" alt="Cloud-Dog AI" '
        'style="vertical-align:middle;border:0">'
        '<span style="font-family:Arial,Helvetica,sans-serif;font-size:16px;font-weight:bold;'
        'color:#0f2037;vertical-align:middle;margin-left:8px">Cloud-Dog AI</span>'
        '</td></tr></table>'
    )


def _footer(note_inline_images: bool) -> str:
    note = ('Images in this report are embedded inline (they may also appear as attachments below). '
            if note_inline_images else '')
    return (
        '<div style="font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#7a8794;'
        'margin-top:16px;padding-top:10px;border-top:1px solid #ccd5df">'
        f'{note}&copy; ' + BRAND_NAME + ' &middot; '
        f'<a href="{WEBSITE}" style="color:#2f6fb0;text-decoration:none">www.cloud-dog.ai</a>'
        '</div>'
    )


def brand_email_body(body, inline_images, has_other_images=False):
    """For SMTP HTML emails: add logo header + footer, attach logo as a CID inline image.
    Idempotent + defensive. Returns (branded_body, inline_images_with_logo)."""
    try:
        if not body or BRAND_LOGO_CID in body:
            return body, inline_images
        branded = _header(f"cid:{BRAND_LOGO_CID}") + body + _footer(has_other_images)
        imgs = list(inline_images or [])
        if not any(isinstance(i, dict) and i.get("content_id") == BRAND_LOGO_CID for i in imgs):
            imgs.append({"content_id": BRAND_LOGO_CID, "content_type": "image/png",
                         "data": CLOUD_DOG_LOGO_B64, "filename": "cloud-dog-ai.png"})
        return branded, imgs
    except Exception:
        return body, inline_images


def brand_pdf_html(html):
    """For generated PDFs: add logo header + footer with the logo as a data URI
    (WeasyPrint embeds data URIs). Idempotent + defensive."""
    try:
        if not html or BRAND_LOGO_CID in html or "cloud-dog-ai-pdf-brand" in html:
            return html
        logo_src = "data:image/png;base64," + CLOUD_DOG_LOGO_B64
        header = '<div id="cloud-dog-ai-pdf-brand">' + _header(logo_src) + '</div>'
        return header + html + _footer(False)
    except Exception:
        return html
